<form class="panel" method="post" action="/admin/ats/job/save" style="max-width:920px"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($j['id'] ?? 0) ?>"><div class="panel-b form">
<div class="row2"><?= a_in('Job title', 'title', $j['title'] ?? '', ['required' => true]) ?><?= a_in('Employer / organisation', 'organisation', $j['organisation'] ?? 'Donums Consultants') ?></div>
<div class="row3"><?= a_in('Location', 'location', $j['location'] ?? '') ?><?= a_sel('Work mode', 'work_mode', JOB_MODES, $j['work_mode'] ?? 'On-site') ?><?= a_sel('Contract type', 'type', JOB_TYPES, $j['type'] ?? 'Full-time') ?></div>
<div class="row3"><?= a_in('Category', 'category', $j['category'] ?? '', ['ph' => 'e.g. Finance, Sales, HR']) ?><?= a_in('Salary (shown publicly)', 'salary_text', $j['salary_text'] ?? '') ?><?= a_in('Application deadline', 'deadline', $j['deadline'] ?? '', ['type' => 'date']) ?></div>
<?= a_in('Role description', 'description', $j['description'] ?? '', ['type' => 'textarea', 'rows' => 9, 'required' => true, 'hint' => 'Supports **bold**, lists and ## headings.']) ?><?= a_in('Requirements', 'requirements', $j['requirements'] ?? '', ['type' => 'textarea', 'rows' => 5]) ?>
<h3 style="margin:6px 0 0">Matching criteria <span class="muted small">— used to calculate each applicant’s fit score</span></h3>
<div class="row3"><?= a_in('Required skills (comma-separated)', 'required_skills', $j['required_skills'] ?? '') ?><?= a_in('Minimum years of experience', 'min_experience', $j['min_experience'] ?? 0, ['type' => 'number', 'min' => 0]) ?><?= a_in('Accepted qualifications (comma-separated)', 'required_quals', $j['required_quals'] ?? '', ['ph' => 'degree, diploma, CPA']) ?></div>
<?= a_in('Screening questions (one per line, up to 6)', 'screening', $j ? implode("\n", json_dec($j['screening'])) : '', ['type' => 'textarea', 'rows' => 3, 'hint' => 'Applicants answer these on the application form.']) ?>
<div class="row3"><?= a_in('Employer contact email', 'employer_email', $j['employer_email'] ?? '', ['type' => 'email']) ?><?= a_in('Employer phone', 'employer_phone', $j['employer_phone'] ?? '') ?><?= a_sel('Status', 'status', ['draft' => 'Draft', 'pending' => 'Pending review', 'published' => 'Published', 'closed' => 'Closed', 'rejected' => 'Rejected'], $j['status'] ?? 'draft') ?></div>
<div class="row2"><?= a_check('Feature on the careers page', 'featured', $j['featured'] ?? 0) ?><?= a_check('Hide the employer’s name (confidential search)', 'confidential', $j['confidential'] ?? 0) ?></div>
<div style="display:flex;gap:10px"><button class="btn btn-primary">Save vacancy</button><?php if ($j): ?><a class="btn btn-ghost" target="_blank" href="/jobs/<?= (int) $j['id'] ?>-<?= e($j['slug']) ?>">Preview</a><?php endif; ?></div></div></form>
